def split_record(text):
    fields = []
    field = []
    escaped = False

    for char in text:
        if escaped:
            field.append(char)
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == "|":
            fields.append("".join(field))
            field = []
        else:
            field.append(char)

    if escaped:
        raise ValueError("terminal unpaired backslash")

    fields.append("".join(field))
    return fields

