from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


def totals(rows):
    grouped = {}

    for row in rows:
        try:
            amount = Decimal(row["amount"])
        except (InvalidOperation, ValueError, TypeError):
            continue

        if not amount.is_finite():
            continue

        account = row["account"].strip()
        grouped.setdefault(account, []).append(amount)

    result = {}
    quantum = Decimal("0.01")

    for account, amounts in grouped.items():
        min_exponent = min(min(value.as_tuple().exponent, -2) for value in amounts)
        max_adjusted = max(value.adjusted() if value else 0 for value in amounts)
        precision = max(1, max_adjusted - min_exponent + len(str(len(amounts))) + 2)

        with localcontext() as context:
            context.prec = precision
            total = sum(amounts, Decimal(0))
            rounded = total.quantize(quantum, rounding=ROUND_HALF_UP)

        result[account] = format(rounded, ".2f")

    return result

