def in_window(t, start, end):
    values = (t, start, end)
    if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
        raise ValueError("t, start, and end must be integers")
    if any(value < 0 or value > 1439 for value in values):
        raise ValueError("t, start, and end must be between 0 and 1439")
    if start == end:
        return False
    if start < end:
        return start <= t < end
    return t >= start or t < end

